using System.IO;
using TMPro;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine;
using UnityEngine.TextCore.LowLevel;
public class MakeFont {
  public static string Main() {
    string src = File.Exists(@"C:\\Windows\\Fonts\\arial.ttf") ? @"C:\\Windows\\Fonts\\arial.ttf" : @"C:\\Windows\\Fonts\\segoeui.ttf";
    string dst = "Assets/FluMix/Art/FluMixUI.ttf";
    File.Copy(src, dst, true);
    AssetDatabase.ImportAsset(dst, ImportAssetOptions.ForceUpdate);
    var importer = AssetImporter.GetAtPath(dst);
    var so = new SerializedObject(importer);
    var prop = so.FindProperty("m_IncludeFontData");
    if (prop != null) { prop.boolValue = true; so.ApplyModifiedPropertiesWithoutUndo(); }
    importer.SaveAndReimport();
    var font = AssetDatabase.LoadAssetAtPath<Font>(dst);
    if (font == null) return "font file missing";
    var asset = TMP_FontAsset.CreateFontAsset(font, 48, 5, GlyphRenderMode.SDFAA, 1024, 1024, AtlasPopulationMode.Dynamic, true);
    if (asset == null) return "create failed";
    string assetPath = "Assets/FluMix/Art/FluMixFont.asset";
    var existing = AssetDatabase.LoadAssetAtPath<TMP_FontAsset>(assetPath);
    if (existing != null) AssetDatabase.DeleteAsset(assetPath);
    AssetDatabase.CreateAsset(asset, assetPath);
    if (asset.material != null && !AssetDatabase.Contains(asset.material)) AssetDatabase.AddObjectToAsset(asset.material, asset);
    if (asset.atlasTextures != null) {
      for (int i = 0; i < asset.atlasTextures.Length; i++) {
        if (asset.atlasTextures[i] != null && !AssetDatabase.Contains(asset.atlasTextures[i])) AssetDatabase.AddObjectToAsset(asset.atlasTextures[i], asset);
      }
    }
    AssetDatabase.SaveAssets();
    string[] scenes = {
      "Assets/FluMix/Scenes/Login.unity",
      "Assets/FluMix/Scenes/HowToPlay.unity",
      "Assets/FluMix/Scenes/Lobby.unity",
      "Assets/FluMix/Scenes/Battle.unity",
      "Assets/FluMix/Scenes/Leaderboard.unity"
    };
    int count = 0;
    foreach (var scenePath in scenes) {
      var scene = EditorSceneManager.OpenScene(scenePath);
      var texts = Object.FindObjectsByType<TMP_Text>(FindObjectsInactive.Include, FindObjectsSortMode.None);
      for (int i = 0; i < texts.Length; i++) { texts[i].font = asset; EditorUtility.SetDirty(texts[i]); count++; }
      EditorSceneManager.SaveScene(scene);
    }
    return "assigned " + count;
  }
}
